import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const project = JSON.parse(await readFile(resolve(ROOT, 'content/project.json'), 'utf8'));

const quote = (value) => JSON.stringify(value);
const importName = (prefix, index) => `${prefix}${index}`;

const lines = [
  '// Generated by scripts/generate-content-registry.mjs.',
  '// Do not edit by hand; edit content/project.json and rerun npm run studio:registry.',
  '',
  "import project from '../../content/project.json' with { type: 'json' };",
];

for (const [index, file] of (project.narrative || []).entries()) {
  lines.push(`import ${importName('story', index)} from '../../content/${file}' with { type: 'json' };`);
}
for (const [index, file] of (project.audio || []).entries()) {
  lines.push(`import ${importName('audio', index)} from '../../content/${file}' with { type: 'json' };`);
}
for (const [index, file] of (project.media || []).entries()) {
  lines.push(`import ${importName('media', index)} from '../../content/${file}' with { type: 'json' };`);
}

lines.push('', 'export const authoringProject = project;');
lines.push(`export const authoringNarrative = [${(project.narrative || []).map((_, index) => importName('story', index)).join(', ')}];`);
lines.push(`export const authoringAudio = [${(project.audio || []).map((_, index) => importName('audio', index)).join(', ')}];`);
lines.push(`export const authoringMedia = [${(project.media || []).map((_, index) => importName('media', index)).join(', ')}];`);
lines.push('export const authoringDocumentsById = new Map(authoringNarrative.map((document) => [document.id, document]));');
lines.push('export const authoringMediaById = new Map(authoringMedia.flatMap((project) => (project.storyArt || []).map((slot) => [slot.id, { ...slot, projectId: project.id }])));');
lines.push('export const authoringAudioProject = authoringAudio[0] || null;');
lines.push(`export const authoringRegistryPaths = ${quote({ narrative: project.narrative || [], audio: project.audio || [], media: project.media || [] })};`);
lines.push('');

await writeFile(resolve(ROOT, 'src/narrative/generated-content.js'), `${lines.join('\n')}\n`, 'utf8');
